<script setup lang="ts">
import {workspaceCompany,replaceCompanyWorkspace} from '../../companyWorkspace';
import AccountingAllCompanies from './AccountingAllCompanies.vue';
import AccountingNotifications from './AccountingNotifications.vue';
import AccountingSingleVouchers from './AccountingSingleVouchers.vue';
import AccountingRoles from './AccountingRoles.vue';
import AccountingApprovals from './AccountingApprovals.vue';
import AccountingSelect from './AccountingSelect.vue';
import {ref,computed,onMounted,onBeforeUnmount,nextTick,provide} from 'vue';
import AccountingOverview from './AccountingOverview.vue';
import AccountingTrade from './AccountingTrade.vue';
import AccountingCashVouchers from './AccountingCashVouchers.vue';
import AccountingTransactions from './AccountingTransactions.vue';
import AdminDialog from '../../AdminDialog.vue';
import './accounting.css';
type Account={debit:string;credit:string;balance:string;balance_side:string;version:number;id:number;company_id:number;parent_id:number|null;code:string;name:string;root_type:string;account_type:string;is_group:boolean;is_system:boolean;active:boolean;description:string|null};
type Data={all_companies?:boolean;can_view_all?:boolean;global_policy?:any;is_super_admin?:boolean;book:any;companies:{id:number;name:string}[];company_id:number|null;role:string;role_name?:string;permissions?:string[];can_manage:boolean;can_delete:boolean;account_types:Record<string,string[]>;accounts:Account[]};
const entrySection=location.hash.slice(1);
const entryId=Number(new URLSearchParams(location.search).get('entry_id'))||undefined;
const selectedLedger=ref(new URLSearchParams(location.search).get('account_id')||''),selectedVoucher=ref<number|undefined>(location.hash==='#single-vouchers'?entryId:undefined);
function openSingle(id:number){selectedVoucher.value=id;navigate('single-vouchers');}
const sections=[{id:'overview',name:'Overview'},{id:'customers',name:'Customers'},{id:'suppliers',name:'Suppliers'},{id:'sales',name:'Sales invoices'},{id:'purchases',name:'Purchase invoices'},{id:'chart',name:'Chart of accounts'},{id:'journals',name:'Journal entries'},{id:'single-vouchers',name:'Single vouchers'},{id:'cash-receipts',name:'Cash receipt vouchers'},{id:'cash-payments',name:'Cash payment vouchers'},{id:'ledger',name:'General Ledger'},{id:'trial',name:'Trial Balance'},{id:'profit',name:'Profit and Loss'},{id:'balance',name:'Balance Sheet'},{id:'receivables',name:'Accounts receivable'},{id:'payables',name:'Accounts payable'},{id:'books',name:'Company books'},{id:'audit',name:'Audit history'},{id:'roles',name:'Roles and permissions'},{id:'approvals',name:'Approvals'}];
const navGroups=[{label:'Workspace',ids:['overview','approvals']},{label:'Sales',ids:['customers','sales']},{label:'Purchases',ids:['suppliers','purchases']},{label:'Accounting',ids:['chart','journals','single-vouchers','cash-receipts','cash-payments','ledger']},{label:'Financial reports',ids:['trial','profit','balance']},{label:'Reports',ids:['receivables','payables']},{label:'Administration',ids:['books','roles','audit']}];
const section=ref(sections.some(s=>s.id===location.hash.slice(1))?location.hash.slice(1):'overview');
function navigate(id:string){section.value=id;history.replaceState(null,'','#'+id);mobileNav.value=false;}
const props=defineProps<{csrf?:string}>();
const choosingCompany=ref(!workspaceCompany('accounting')),companyChoice=ref(''),choiceError=ref(''),companySearch=ref('');
function leaveAccounting(){location.assign('/products/accounts');}
function chooseCompany(id:string){if(loading.value)return;companyChoice.value=id;void confirmCompany();}
async function confirmCompany(){if(!companyChoice.value){choiceError.value='Select a company to continue.';return;}choiceError.value='';company.value=companyChoice.value;await load(true,true);if(!error.value)choosingCompany.value=false;}

const data=ref<Data|null>(null),company=ref(workspaceCompany('accounting')||''),search=ref(''),root=ref(''),kind=ref(''),state=ref(''),selectedId=ref<number|null>(null),expanded=ref(new Set<number>()),loading=ref(true),busy=ref(false),error=ref(''),formError=ref(''),notice=ref(''),failed=ref(false),modal=ref(''),mobileNav=ref(false);
const availableCompanies=computed(()=>(data.value?.companies||[]).filter(c=>c.name.toLowerCase().includes(companySearch.value.trim().toLowerCase())));
provide('accounting-permissions',computed(()=>data.value?.permissions));
provide('accounting-legacy',computed(()=>({manage:!!data.value?.can_manage,admin:!!data.value?.can_delete})));
function can(key:string):boolean{if(key==='vouchers.view')return ['cash_receipts','cash_payments','bank_receipts','bank_payments','expense_vouchers','income_vouchers'].some(g=>can(g+'.view'));if(data.value?.permissions)return data.value.permissions.includes(key);if(key==='audit.view'||key.endsWith('.delete')||key.endsWith('.reverse')||key==='books.manage'||key==='roles.manage')return !!data.value?.can_delete;if(key.endsWith('.view')||key.endsWith('.print')||(key.startsWith('reports.')&&key!=='reports.export'))return true;return !!data.value?.can_manage;}
const sectionPermission=(id:string)=>({'single-vouchers':'vouchers.view',overview:'overview.view',chart:'chart.view',approvals:'workflow.view',roles:'roles.view',journals:'journals.view','cash-receipts':'cash_receipts.view','cash-payments':'cash_payments.view',books:'books.view',audit:'audit.view',customers:'customers.view',suppliers:'suppliers.view',sales:'sales.view',purchases:'purchases.view'} as Record<string,string>)[id]||'reports.'+id;
const childParent=ref<Account|null>(null);
function chooseChild(asGroup:boolean){const parent=childParent.value;childParent.value=null;if(parent)open('create',parent,asGroup);}
const form=ref<any>({});let version=0,timer:ReturnType<typeof setTimeout>|undefined;
const accounts=computed(()=>data.value?.accounts||[]),selected=computed(()=>accounts.value.find(a=>a.id===selectedId.value));
const companyName=computed(()=>company.value==='all'?'All companies':data.value?.companies.find(c=>String(c.id)===company.value)?.name||'Select a company');
const matching=(a:Account)=>(!root.value||a.root_type===root.value)&&(!kind.value||(kind.value==='group')===a.is_group)&&(!state.value||(state.value==='active')===a.active)&&(!search.value||[a.code,a.name,a.description||''].join(' ').toLowerCase().includes(search.value.toLowerCase()));
const filtering=computed(()=>!!(search.value||root.value||kind.value||state.value));
const matches=computed(()=>accounts.value.filter(matching));
const children=computed(()=>{const map=new Map<number|null,Account[]>();for(const a of accounts.value)map.set(a.parent_id,[...(map.get(a.parent_id)||[]),a]);return map;});
const rows=computed(()=>{const allowed=new Set<number>();for(const a of matches.value){let cursor:Account|undefined=a;while(cursor&&!allowed.has(cursor.id)){allowed.add(cursor.id);cursor=accounts.value.find(p=>p.id===cursor!.parent_id);}}
 const result:{account:Account;depth:number;hasChildren:boolean;last:boolean;guides:boolean[]}[]=[];const visited=new Set<number>();function walk(parent:number|null,depth:number,guides:boolean[]=[]){const siblings=(children.value.get(parent)||[]).filter(a=>allowed.has(a.id)&&!visited.has(a.id));siblings.forEach((a,index)=>{visited.add(a.id);const kids=children.value.get(a.id)||[];const last=index===siblings.length-1;result.push({account:a,depth,hasChildren:kids.length>0,last,guides:guides.slice(1)});if(filtering.value||expanded.value.has(a.id))walk(a.id,depth+1,[...guides,!last]);});}walk(null,0);return result;});
const path=computed(()=>{const result:Account[]=[];let current=selected.value;const seen=new Set<number>();while(current&&!seen.has(current.id)){seen.add(current.id);result.unshift(current);current=accounts.value.find(a=>a.id===current!.parent_id);}return result;});
const parents=computed(()=>accounts.value.filter(a=>{if(!a.is_group||a.root_type!==form.value.root_type||form.value.active&&!a.active)return false;let cursor:Account|undefined=a;const seen=new Set<number>();while(cursor&&!seen.has(cursor.id)){if(cursor.id===form.value.id)return false;seen.add(cursor.id);cursor=accounts.value.find(p=>p.id===cursor!.parent_id);}return true;}));
function notify(message:string,isError=false){notice.value=message;failed.value=isError;clearTimeout(timer);timer=setTimeout(()=>notice.value='',4500);}
async function api(path:string,body?:any,method='POST'){const requestUrl=new URL('/accounting/api/'+path,location.origin);const group=new URLSearchParams(location.search).get('workspace_group');if(group)requestUrl.searchParams.set('workspace_group',group);const response=await fetch(requestUrl,{method:body?method:'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const result=await response.json();if(!response.ok)throw Object.assign(Error(Object.values(result.errors||{}).flat().join(' ')||result.message||'Unable to complete this action.'),{status:response.status});return result;}
async function load(reset=false,confirmed=false){const current=++version;loading.value=true;error.value='';try{const result=await api('data'+(choosingCompany.value&&!confirmed?'?choose=1':company.value?'?company_id='+company.value:''));if(current!==version)return;data.value=result;company.value=result.all_companies?'all':String(result.company_id||'');if(choosingCompany.value&&!confirmed)return;replaceCompanyWorkspace('accounting',company.value);if(reset){selectedId.value=null;search.value='';root.value='';kind.value='';state.value='';}if(reset||!expanded.value.size)expanded.value=new Set(result.accounts.filter((a:Account)=>a.is_group).map((a:Account)=>a.id));if(selectedId.value&&!result.accounts.some((a:Account)=>a.id===selectedId.value))selectedId.value=null;}catch(e){if(current===version)error.value=(e as Error).message;}finally{if(current===version)loading.value=false;}}
function toggle(id:number){const next=new Set(expanded.value);next.has(id)?next.delete(id):next.add(id);expanded.value=next;}
function open(kind:string,account?:Account,asGroup=false){formError.value='';modal.value=kind;if(kind==='edit'&&account)form.value={...account};else if(kind==='delete')form.value={...account};else if(kind==='create'){const parent=account?.is_group?account:accounts.value.find(a=>a.is_system&&a.root_type===(selected.value?.root_type||'Asset'));form.value={company_id:Number(company.value),parent_id:parent?.id||'',code:'',name:'',root_type:parent?.root_type||'Asset',account_type:'General',is_group:asGroup,active:true,description:''};}}
const codePreview=computed(()=>{const parent=accounts.value.find(a=>a.id===Number(form.value.parent_id));if(!parent)return 'Select a parent group';let next=1;for(const a of accounts.value){const prefix=parent.code+'-';if(a.code.startsWith(prefix)&&/^\d+$/.test(a.code.slice(prefix.length)))next=Math.max(next,Number(a.code.slice(prefix.length))+1);}return parent.code+'-'+String(next).padStart(2,'0');});
function amount(value:string){return Number(value||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});}
function resetParent(){form.value.parent_id='';form.value.account_type='General';}
async function save(next:'close'|'child'='close'){if(busy.value)return;busy.value=true;formError.value='';try{let response;if(modal.value==='initialize')response=await api('initialize',{company_id:Number(company.value)});else if(modal.value==='delete')response=await api('accounts/'+form.value.id,{company_id:Number(company.value),version:form.value.version},'DELETE');else response=await api('accounts',form.value);if(response.account)selectedId.value=response.account.id;modal.value='';notify(response.message);await load();if(response.account){const ancestors=new Set(expanded.value);let current=accounts.value.find(a=>a.id===response.account.id);while(current?.parent_id){ancestors.add(current.parent_id);current=accounts.value.find(a=>a.id===current!.parent_id);}expanded.value=ancestors;await nextTick();document.querySelector('[data-account-id="'+response.account.id+'"]')?.scrollIntoView({block:'nearest',behavior:'smooth'});if(next==='child'&&response.account.is_group)open('create',response.account);}}catch(e){formError.value=(e as Error).message;notify(formError.value,true);if((e as any).status===409)await load();}finally{busy.value=false;}}
function filterReset(){search.value='';root.value='';kind.value='';state.value='';}
onMounted(async()=>{await load(true);if(section.value==='chart'&&entryId){selectedId.value=entryId;await nextTick();document.querySelector('[data-account-id="'+entryId+'"]')?.scrollIntoView({block:'nearest'});}});onBeforeUnmount(()=>{version++;clearTimeout(timer);});
</script>
<template><div class="ac-workspace">
<div v-if="notice" class="judibas-toast" :class="{error:failed}" role="status">{{notice}}</div>
<header class="ac-heading"><div><p class="eyebrow">JUDIBAS / FINANCE</p><h1>Accounting</h1><p class="muted">A clear foundation for your company's finances.</p></div><div class="ac-heading-tools"><AccountingNotifications v-if="!choosingCompany&&data&&can('notifications.view')" :company="data.company_id" :csrf="csrf"/></div></header>
<AdminDialog v-if="choosingCompany" title="Choose a company" subtitle="Open an Accounting workspace." :busy="loading" dialog-class="ac-company-dialog" @close="leaveAccounting"><div class="ac-company-picker"><label class="ac-company-search">Search companies<input v-model="companySearch" type="search" placeholder="Find a company..." :disabled="loading" autocomplete="off"></label><p v-if="error||choiceError" class="notice admin-error" role="alert">{{error||choiceError}}</p><p v-if="loading" class="ac-company-loading" role="status"><span class="ac-spinner"></span>{{companyChoice?'Opening company accounts...':'Loading companies...'}}</p><div class="ac-company-options" aria-label="Available accounting companies"><button v-if="data?.can_view_all&&(!companySearch||'all companies'.includes(companySearch.toLowerCase()))" type="button" class="ac-company-option" :disabled="loading" @click="chooseCompany('all')"><span class="ac-company-symbol" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M3 21V8h7v13M10 21V3h11v18M6 12h1m-1 4h1m7-9h1m3 0h1m-5 4h1m3 0h1m-5 4h1m3 0h1M1 21h22"/></svg></span><span><strong>All companies</strong><small>Combined Accounting view</small></span><span class="ac-company-arrow" aria-hidden="true">&#8594;</span></button><button v-for="c in availableCompanies" :key="c.id" type="button" class="ac-company-option" :disabled="loading" @click="chooseCompany(String(c.id))"><span class="ac-company-symbol" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M5 21V3h14v18M3 21h18M9 7h2m2 0h2m-6 4h2m2 0h2M9 21v-6h6v6"/></svg></span><span><strong>{{c.name}}</strong></span><span class="ac-company-arrow" aria-hidden="true">&#8594;</span></button><p v-if="!loading&&!availableCompanies.length&&(!data?.can_view_all||companySearch&&!('all companies'.includes(companySearch.toLowerCase())))" class="ac-company-empty">{{data?.companies.length?'No matching companies.':'No companies are assigned to your account.'}}</p></div><div class="ac-company-picker-footer"><small>Select a company to open its accounts.</small><a href="/products/accounts">Back to overview</a></div></div></AdminDialog><div class="ac-layout"><aside class="ac-sidebar"><button class="ac-mobile-nav" type="button" :aria-expanded="mobileNav" @click="mobileNav=!mobileNav">Accounting navigation <span aria-hidden="true">{{mobileNav?'-':'+'}}</span></button><nav aria-label="Accounting navigation" :class="{open:mobileNav}"><template v-for="group in navGroups.filter(g=>sections.some(s=>g.ids.includes(s.id)&&can(sectionPermission(s.id))))" :key="group.label"><p class="eyebrow ac-nav-group">{{group.label}}</p><button v-for="item in sections.filter(s=>group.ids.includes(s.id)&&(can(sectionPermission(s.id))))" :key="item.id" type="button" :class="{active:section===item.id}" :aria-current="section===item.id?'page':undefined" @click="navigate(item.id)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path :d="['sales','purchases','journals'].includes(item.id)?'M6 3h12v18H6z M9 8h6 M9 12h6 M9 16h4':['customers','suppliers'].includes(item.id)?'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 8h5 M19.5 5.5v5':'M4 20h16 M6 16V9 M12 16V4 M18 16v-6'"/></svg>{{item.name}}</button></template><a href="/products">All products <span aria-hidden="true">&#8599;</span></a></nav><div class="ac-scope"><strong>{{companyName}}</strong><small>{{data?.role_name||({manager:'Accounting Manager',accountant:'Accountant',viewer:'Read-only access'} as any)[data?.role||'viewer']}}</small></div></aside>
<main class="ac-main" :aria-busy="loading"><div v-if="choosingCompany" class="ac-empty"><h2>Select your Accounting workspace</h2><p>Choose a company in the dialog to continue.</p></div><div v-else-if="data&&!can(sectionPermission(section))" class="ac-empty"><h2>Choose an available workspace</h2><p>Your Accounting role controls the pages and actions you can use.</p><button v-for="item in sections.filter(s=>can(sectionPermission(s.id)))" :key="item.id" class="button" @click="navigate(item.id)">{{item.name}}</button></div><AccountingRoles :open-id="section===entrySection?entryId:undefined" v-else-if="section==='roles'" :csrf="csrf" @notice="notify($event)" @changed="load()"/><AccountingAllCompanies v-else-if="data?.all_companies" :section="section" @navigate="navigate"/><AccountingApprovals :open-id="section===entrySection?entryId:undefined" v-else-if="section==='approvals'&&data?.company_id" :company="data.company_id" :accounts="accounts" :csrf="csrf" @notice="notify($event)"/><AccountingOverview v-else-if="section==='overview'&&data?.company_id" :company="data.company_id" :book="data.book" @navigate="navigate"/><AccountingTrade v-else-if="['customers','suppliers','sales','purchases'].includes(section)&&data?.company_id" :key="'trade-'+data.company_id" :open-id="section===entrySection?entryId:undefined" :section="section" :company="data.company_id" :book="data.book" :accounts="accounts" :can-manage="data.can_manage" :can-admin="data.can_delete" :csrf="csrf" @notice="notify($event)" @setup="navigate('books')"/><AccountingSingleVouchers v-else-if="section==='single-vouchers'&&data?.company_id" :key="'single-'+data.company_id" :company="data.company_id" :accounts="accounts" :book="data.book" :csrf="csrf" :open-id="selectedVoucher" @notice="notify($event)"/><AccountingCashVouchers v-else-if="['cash-receipts','cash-payments'].includes(section)&&data?.company_id" :key="'cash-'+section+'-'+data.company_id" @single="openSingle" :kind="section==='cash-receipts'?'cash_receipt':'cash_payment'" :company="data.company_id" :book="data.book" :accounts="accounts" :can-manage="data.can_manage" :can-admin="data.can_delete" :csrf="csrf" @notice="notify($event)" @changed="load()" @setup="navigate('books')"/><AccountingTransactions v-else-if="section!=='chart'&&data?.company_id" :key="data.company_id" :section="section" :company="data.company_id" :open-id="section===entrySection?entryId:undefined" :global-policy="data.global_policy" :is-super-admin="data.is_super_admin" :company-name="companyName" :book="data.book" :accounts="accounts" :can-manage="data.can_manage" :can-admin="data.can_delete" :csrf="csrf" @ledger="selectedLedger=String($event);navigate('ledger')" :initial-account="selectedLedger" @setup="navigate('books')" @changed="load()" @notice="notify($event)"/><template v-else><div class="ac-section-heading"><div><h2>Chart of accounts <small class="muted">/ {{companyName}}</small></h2><p class="muted">Organise accounts into Assets, Liabilities, Equity, Income and Expenses.</p></div><button v-if="can('chart.create')&&accounts.length" class="button primary" :disabled="busy||loading" @click="open('create',selected)">+ Create account</button></div>
<p v-if="error" class="notice admin-error" role="alert">{{error}} <button class="button" @click="load()">Try again</button></p><p v-if="loading&&!data" role="status">Loading your chart...</p>
<template v-if="data&&!error"><div v-if="!data.companies.length" class="ac-empty"><h3>No company assigned</h3><p>Ask your administrator to assign a company to your Accounting access.</p></div>
<div v-else-if="!accounts.length&&!loading" class="ac-empty"><span class="ac-empty-icon" aria-hidden="true">&#8801;</span><h3>Start your company's chart</h3><p>Create a starter structure with five protected root groups and common service-business accounts. You can adapt the account codes and groups to your needs.</p><button v-if="can('chart.initialize')" class="button primary" @click="open('initialize')">Set up chart of accounts</button><p v-else class="muted">An accountant or administrator can set up this company's chart.</p></div>
<template v-else-if="accounts.length"><div v-if="accounts.every(a=>Number(a.debit||0)===0&&Number(a.credit||0)===0)" class="ac-help"><strong>No posted transactions for {{companyName}}.</strong><p>Balances are zero until opening balances or transactions are posted. Creating accounts alone does not create money.</p><button v-if="data.can_manage" class="button" @click="navigate(data.book?'journals':'books')">{{data.book?'Create a journal entry':'Set up company books'}}</button><button v-if="data.companies.some(c=>c.name==='Judibas Realistic Accounts Demo (TEST ONLY)')" class="button" @click="company=String(data.companies.find(c=>c.name==='Judibas Realistic Accounts Demo (TEST ONLY)')!.id);load(true)">View populated testing company</button></div><div class="ac-stats"><article><small>Total accounts</small><strong>{{accounts.length}}</strong></article><article><small>Groups</small><strong>{{accounts.filter(a=>a.is_group).length}}</strong></article><article><small>Ledger accounts</small><strong>{{accounts.filter(a=>!a.is_group).length}}</strong></article><article><small>Inactive</small><strong>{{accounts.filter(a=>!a.active).length}}</strong></article></div>
<div class="ac-filters"><label class="ac-search">Find an account<input type="search" v-model="search" placeholder="Search by code, name or description"></label><label>Root type<AccountingSelect><select v-model="root"><option value="">All root types</option><option v-for="(_,name) in data.account_types" :key="name" :value="name">{{name}}</option></select></AccountingSelect></label><label>Account kind<AccountingSelect><select v-model="kind"><option value="">All accounts</option><option value="group">Groups</option><option value="ledger">Ledger accounts</option></select></AccountingSelect></label><label>Status<AccountingSelect><select v-model="state"><option value="">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option></select></AccountingSelect></label><button v-if="filtering" type="button" class="button" @click="filterReset">Clear filters</button></div>
<div class="ac-chart-layout" :class="{'has-selection':!!selected}"><section class="ac-tree-panel" :style="{'--tree-width':Math.max(780,620+Math.max(0,...rows.map(r=>r.depth))*24)+'px'}"><header><div><h3>Account hierarchy</h3><small class="muted">{{filtering?matches.length+' matching accounts':'Select an account to view its details'}}</small></div><div class="ac-tree-controls"><button type="button" @click="expanded=new Set(accounts.filter(a=>a.is_group).map(a=>a.id))">Expand all</button><button type="button" @click="expanded=new Set()">Collapse all</button></div></header>
<div class="ac-chart-columns"><span>Account code / name</span><span>Debit</span><span>Credit</span><span>Balance</span><span>Status</span></div><div class="ac-tree" role="tree" aria-label="Chart of accounts"><div v-for="row in rows" :key="row.account.id" role="treeitem" :aria-level="row.depth+1" :aria-expanded="row.account.is_group?(filtering||expanded.has(row.account.id)):undefined" :aria-selected="selectedId===row.account.id" :data-account-id="row.account.id" class="ac-tree-row" :class="{selected:selectedId===row.account.id,inactive:!row.account.active,context:filtering&&!matching(row.account),group:row.account.is_group,root:row.account.is_system}" :style="{'--depth':row.depth}"><span class="ac-tree-connectors" aria-hidden="true"><span v-for="(continues,index) in row.guides" :key="index" v-show="continues" class="ac-tree-guide" :style="{'--guide-level':index}"></span><span v-if="row.depth" class="ac-tree-elbow" :class="{'is-last':row.last}"></span><span v-if="row.hasChildren&&(filtering||expanded.has(row.account.id))" class="ac-tree-stem"></span></span><button v-if="row.hasChildren" type="button" class="ac-toggle" :aria-label="(expanded.has(row.account.id)?'Collapse ':'Expand ')+row.account.name" @click="toggle(row.account.id)"><svg viewBox="0 0 20 20" :class="{rotated:filtering||expanded.has(row.account.id)}" aria-hidden="true"><path d="m7 4 6 6-6 6"/></svg></button><span v-else class="ac-toggle-spacer"></span><button v-if="can('chart.create')&&row.account.is_group&&row.account.active" type="button" class="ac-inline-child" :disabled="busy||loading" :aria-label="'Add child to '+row.account.name" title="Add subgroup or ledger account" @click="childParent=row.account">+</button><button type="button" class="ac-account" @click="selectedId=row.account.id"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path :d="row.account.is_group?'M3 6h7l2 2h9v12H3z':'M6 3h12v18H6z M9 8h6 M9 12h6 M9 16h4'"/></svg><code>{{row.account.code}}</code><span>{{row.account.name}}<small>{{row.account.is_group?'Group':'Ledger account'}}{{!row.account.active?' / Inactive':''}}</small></span></button><span class="ac-chart-amount">{{amount(row.account.debit)}}</span><span class="ac-chart-amount">{{amount(row.account.credit)}}</span><span class="ac-chart-amount">{{amount(row.account.balance)}} <small>{{row.account.balance_side}}</small></span><span class="ac-chart-state" :class="{inactive:!row.account.active}">{{row.account.active?'Active':'Inactive'}}</span></div></div><p v-if="!rows.length" class="ac-empty-small">No matching accounts. Try another search or clear the filters.</p></section>
<aside v-if="selected" class="ac-detail"><template v-if="selected"><div class="ac-detail-heading"><button type="button" class="ac-detail-close" aria-label="Close account details" @click="selectedId=null">&times;</button><span class="ac-badge" :class="selected.active?'active':'inactive'">{{selected.active?'Active':'Inactive'}}</span><span class="muted">{{selected.is_group?'Group account':'Ledger account'}}</span></div><code class="ac-detail-code">{{selected.code}}</code><h3>{{selected.name}}</h3><p class="ac-path">{{path.map(a=>a.name).join(' / ')}}</p><dl><div><dt>Debit total</dt><dd>{{amount(selected.debit)}}</dd></div><div><dt>Credit total</dt><dd>{{amount(selected.credit)}}</dd></div><div><dt>Balance</dt><dd>{{amount(selected.balance)}} {{selected.balance_side}}</dd></div><div><dt>Root type</dt><dd>{{selected.root_type}}</dd></div><div><dt>Account type</dt><dd>{{selected.account_type}}</dd></div><div><dt>Parent group</dt><dd>{{accounts.find(a=>a.id===selected?.parent_id)?.name||'Root group'}}</dd></div></dl><p class="ac-description">{{selected.description||'No description added.'}}</p><p v-if="selected.is_system" class="ac-help">This root group keeps the account tree organised. Manage the accounts below it.</p><div class="ac-detail-actions"><button v-if="can('chart.create')&&selected.is_group&&selected.active" class="button primary" :disabled="busy||loading" @click="open('create',selected)">Add ledger account</button><button v-if="can('chart.create')&&selected.is_group&&selected.active" class="button" :disabled="busy||loading" @click="open('create',selected,true)">Add subgroup</button><button v-if="can('chart.update')&&!selected.is_system" class="button" :disabled="busy||loading" @click="open('edit',selected)">Edit account</button><button v-if="can('chart.delete')&&!selected.is_system" class="button ac-danger" :disabled="busy||loading" @click="open('delete',selected)">Delete</button></div></template><template v-else><span class="eyebrow">ACCOUNT DETAILS</span><h3>A place for every account</h3><p class="muted">Select a group or ledger account to see its position in the chart and available actions.</p></template></aside></div>
<p class="ac-stage-note">Balances as of today in {{data.book?.currency||'PKR'}}. Posted entries only, including reversals; drafts are excluded. Group totals include all descendants. Dr = debit balance; Cr = credit balance. Capital appears under Equity. Refresh to retrieve the latest balances.</p></template></template></template></main></div>
<AdminDialog v-if="childParent" title="Add child account" dialog-class="ac-dialog" @close="childParent=null"><p class="ac-help">Create beneath <strong>{{childParent.code}} ? {{childParent.name}}</strong>.</p><div class="ac-child-choices"><button type="button" @click="chooseChild(true)"><strong>+ Add subgroup</strong><span>Organise more groups and ledger accounts underneath it.</span></button><button type="button" @click="chooseChild(false)"><strong>+ Add ledger account</strong><span>Record transactions against this account.</span></button></div></AdminDialog>
<AdminDialog v-if="modal" :title="modal==='initialize'?'Set up chart of accounts':modal==='delete'?'Delete account':modal==='edit'?'Edit account':'Create account'" :busy="busy" dialog-class="ac-dialog" @close="!busy&&(modal='')"><form @submit.prevent="save()"><p v-if="formError" class="notice admin-error" role="alert">{{formError}}</p>
<template v-if="modal==='initialize'"><p>Create a starter chart for <strong>{{companyName}}</strong>?</p><p class="muted">Includes Assets, Liabilities, Equity, Income and Expenses, with common accounts for cash, bank, receivables, payables and service-business costs. No balances or transactions are created.</p><p class="ac-help">Review the structure with your accountant. This is a starting point, not a country-specific statutory template.</p></template>
<template v-else-if="modal==='delete'"><p>Delete <strong>{{form.code}} - {{form.name}}</strong>?</p><p class="muted">Groups containing accounts cannot be deleted. You can deactivate an account instead to keep its structure.</p></template>
<template v-else><p class="ac-help">{{form.is_group?'Group: create subgroups or ledger accounts beneath it. Groups cannot receive transactions directly.':'Ledger account: use it for transactions. To create further children, choose Group instead.'}}</p><div class="ac-form-grid"><label>Account code<input v-if="form.id" v-model="form.code" required maxlength="255" :disabled="busy"><input v-else aria-label="Account code" :value="codePreview" readonly><small v-if="!form.id" class="muted">Assigned automatically when saved. Preview may change if another account is created.</small></label><label>Account name<input v-model="form.name" required maxlength="150" placeholder="e.g. Internet and telephone" :disabled="busy"></label><label>Root type<AccountingSelect><select aria-label="Root type" v-model="form.root_type" :disabled="!!form.id||busy" @change="resetParent"><option v-for="(_,name) in data?.account_types" :key="name">{{name}}</option></select></AccountingSelect></label><label>Account kind<AccountingSelect><select aria-label="Account kind" v-model="form.is_group" :disabled="!!form.id||busy" @change="form.account_type='General'"><option :value="false">Ledger account</option><option :value="true">Group ? contains child accounts</option></select></AccountingSelect></label><label>Parent group<AccountingSelect><select aria-label="Parent group" v-model.number="form.parent_id" required :disabled="busy"><option value="">Select a parent group</option><option v-for="parent in parents" :key="parent.id" :value="parent.id">{{parent.code}} - {{parent.name}}</option></select></AccountingSelect></label><label>Account type<AccountingSelect><select aria-label="Account type" v-model="form.account_type" :disabled="form.is_group||busy"><option v-for="type in data?.account_types[form.root_type]||[]" :key="type">{{type}}</option></select></AccountingSelect></label></div><label>Description<textarea v-model="form.description" rows="3" maxlength="2000" :disabled="busy" placeholder="Explain what belongs in this account"></textarea></label><label class="ac-check"><input type="checkbox" v-model="form.active" :disabled="busy">Active account</label></template>
<div class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="modal=''">Cancel</button><button v-if="modal==='create'&&form.is_group" type="button" class="button" :disabled="busy" @click="($event.currentTarget as HTMLButtonElement).form?.reportValidity()&&save('child')">Save and add child</button><button class="button primary" :class="{'ac-delete-button':modal==='delete'}" :disabled="busy" :aria-busy="busy"><span v-if="busy" class="ac-spinner" aria-hidden="true"></span>{{busy?'Saving...':modal==='initialize'?'Create starter chart':modal==='delete'?'Delete account':'Save account'}}</button></div></form></AdminDialog>
</div></template>
